function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // surveillance camera
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();

  // lens
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();

  // eye movement
  ctx.beginPath();
  ctx.arc(W/2 + 30*Math.sin(t), H/2 + 30*Math.cos(t), 10, 0, 2*Math.PI);
  ctx.stroke();

  // big brother
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 100, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 120);
  ctx.lineTo(W/2, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 135);
  ctx.lineTo(W/2 - 20, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 135);
  ctx.lineTo(W/2 + 20, H/2 + 120);
  ctx.stroke();

  // surveillance lines
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2, H/2);
    ctx.lineTo(W/2 + 100*Math.sin(t + i), H/2 + 100*Math.cos(t + i));
    ctx.stroke();
  }

  ctx.restore();
}
